CREATE TYPE public.app_role AS ENUM ('participant','organizer','admin');
GRANT USAGE ON TYPE public.app_role TO authenticated, service_role;

CREATE TABLE public.profiles (
 id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
 full_name text NOT NULL DEFAULT '', email text, phone text, address text, department text, course text,
 preferences text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "profile owner read" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "profile owner create" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE POLICY "profile owner update" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);

CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user reads own role" ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) AND (_user_id = auth.uid() OR EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin')) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO anon, authenticated, service_role;
CREATE POLICY "admin reads roles" ON public.user_roles FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));

CREATE TABLE public.categories (id integer PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', accent text NOT NULL DEFAULT '');
GRANT SELECT ON public.categories TO anon, authenticated;
GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "categories public read" ON public.categories FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE public.festivals (id integer GENERATED BY DEFAULT AS IDENTITY (START WITH 100) PRIMARY KEY, name text NOT NULL, tagline text NOT NULL DEFAULT '', theme text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', start_date date NOT NULL, end_date date NOT NULL, banner text NOT NULL DEFAULT 'hero_festival.jpg', created_by uuid);
GRANT SELECT ON public.festivals TO anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.festivals_id_seq TO authenticated, service_role;
GRANT INSERT, UPDATE, DELETE ON public.festivals TO authenticated;
GRANT ALL ON public.festivals TO service_role;
ALTER TABLE public.festivals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "festivals public read" ON public.festivals FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "festivals admin manage" ON public.festivals FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));

CREATE TABLE public.events (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id integer NOT NULL REFERENCES public.categories(id), max_seats integer NOT NULL DEFAULT 50 CHECK (max_seats > 0), name text NOT NULL DEFAULT '', subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', venue text NOT NULL DEFAULT '', start_at timestamptz NOT NULL DEFAULT now(), end_at timestamptz NOT NULL DEFAULT now() + interval '2 hours', price integer NOT NULL DEFAULT 0 CHECK(price >= 0), poster text NOT NULL DEFAULT 'hero_festival.jpg', festival_id integer REFERENCES public.festivals(id), featured boolean NOT NULL DEFAULT false, artists jsonb NOT NULL DEFAULT '[]'::jsonb, terms text NOT NULL DEFAULT '', organiser_id uuid, published boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.events TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.events TO authenticated;
GRANT ALL ON public.events TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.events_id_seq TO authenticated, service_role;
ALTER TABLE public.events ALTER COLUMN id RESTART WITH 1000;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "events public or owned read" ON public.events FOR SELECT TO anon, authenticated USING (published OR organiser_id = auth.uid() OR public.has_role(auth.uid(),'admin'));

CREATE TABLE public.achievements (code text PRIMARY KEY, title text NOT NULL, criteria text NOT NULL DEFAULT '', artwork text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'badge', points integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.achievements TO anon, authenticated;
GRANT ALL ON public.achievements TO service_role;
ALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "achievements public read" ON public.achievements FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE public.voucher_campaigns (id integer PRIMARY KEY, title text NOT NULL, type text NOT NULL DEFAULT '', pct integer NOT NULL DEFAULT 0, description text NOT NULL DEFAULT '', valid_until date, stock integer NOT NULL DEFAULT 200);
GRANT SELECT ON public.voucher_campaigns TO anon, authenticated;
GRANT UPDATE ON public.voucher_campaigns TO authenticated;
GRANT ALL ON public.voucher_campaigns TO service_role;
ALTER TABLE public.voucher_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY "voucher campaigns public read" ON public.voucher_campaigns FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "admin manages voucher stock" ON public.voucher_campaigns FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));

CREATE TABLE public.organiser_profiles (user_id uuid PRIMARY KEY, org_name text NOT NULL DEFAULT '', position text NOT NULL DEFAULT '', org_type text NOT NULL DEFAULT '', institutional_id text, description text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), review_note text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.organiser_profiles TO authenticated;
GRANT ALL ON public.organiser_profiles TO service_role;
ALTER TABLE public.organiser_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "organiser reads application" ON public.organiser_profiles FOR SELECT TO authenticated USING (auth.uid() = user_id OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "organiser submits own application" ON public.organiser_profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id AND status = 'pending');
CREATE POLICY "admin reviews organiser application" ON public.organiser_profiles FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));

CREATE TABLE public.admin_profiles (user_id uuid PRIMARY KEY, office text NOT NULL DEFAULT '', designation text NOT NULL DEFAULT '', staff_id text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_profiles TO authenticated;
GRANT ALL ON public.admin_profiles TO service_role;
ALTER TABLE public.admin_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin application own or admin read" ON public.admin_profiles FOR SELECT TO authenticated USING (auth.uid() = user_id OR public.has_role(auth.uid(),'admin'));

CREATE OR REPLACE FUNCTION public.is_approved_organiser(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_uid,'organizer') AND EXISTS (SELECT 1 FROM public.organiser_profiles WHERE user_id=_uid AND status='approved') $$;
REVOKE EXECUTE ON FUNCTION public.is_approved_organiser(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_approved_organiser(uuid) TO authenticated, service_role;
CREATE POLICY "events insert by approved organisers or admins" ON public.events FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin') OR (organiser_id = auth.uid() AND public.is_approved_organiser(auth.uid())));
CREATE POLICY "events update by owner or admin" ON public.events FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin') OR (organiser_id = auth.uid() AND public.is_approved_organiser(auth.uid()))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (organiser_id = auth.uid() AND public.is_approved_organiser(auth.uid())));
CREATE POLICY "events delete by owner or admin" ON public.events FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin') OR (organiser_id = auth.uid() AND public.is_approved_organiser(auth.uid())));
CREATE OR REPLACE FUNCTION public.events_no_clash() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE other text; BEGIN IF NEW.end_at <= NEW.start_at THEN RAISE EXCEPTION 'CLASH: event must end after it starts'; END IF; IF NEW.organiser_id IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtext(NEW.organiser_id::text)); SELECT name INTO other FROM public.events WHERE organiser_id=NEW.organiser_id AND id<>NEW.id AND tstzrange(start_at,end_at) && tstzrange(NEW.start_at,NEW.end_at) LIMIT 1; IF other IS NOT NULL THEN RAISE EXCEPTION 'CLASH: overlaps your event "%"', other; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER events_no_clash BEFORE INSERT OR UPDATE OF start_at,end_at,organiser_id ON public.events FOR EACH ROW EXECUTE FUNCTION public.events_no_clash();
CREATE OR REPLACE FUNCTION public.event_clashes() RETURNS TABLE(a_id integer, a_name text, b_id integer, b_name text, venue text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT a.id,a.name,b.id,b.name,a.venue FROM public.events a JOIN public.events b ON a.id < b.id AND a.venue=b.venue AND tstzrange(a.start_at,a.end_at) && tstzrange(b.start_at,b.end_at) WHERE public.has_role(auth.uid(),'admin') $$;
REVOKE EXECUTE ON FUNCTION public.event_clashes() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.event_clashes() TO authenticated;

CREATE TABLE public.registrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event_id integer NOT NULL REFERENCES public.events(id), kind text NOT NULL DEFAULT 'booked' CHECK(kind IN ('booked','planned')), pass_code text NOT NULL DEFAULT upper(substr(md5(random()::text),1,8)), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_id));
GRANT SELECT, INSERT, DELETE ON public.registrations TO authenticated;
GRANT ALL ON public.registrations TO service_role;
ALTER TABLE public.registrations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "registrations owner event manager or admin read" ON public.registrations FOR SELECT TO authenticated USING (auth.uid()=user_id OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND organiser_id=auth.uid()));
CREATE POLICY "participant registers for published events" ON public.registrations FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id AND public.has_role(auth.uid(),'participant') AND EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND published));
CREATE POLICY "owner cancels own registration" ON public.registrations FOR DELETE TO authenticated USING (auth.uid()=user_id AND public.has_role(auth.uid(),'participant'));
CREATE OR REPLACE FUNCTION public.registration_capacity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE seats integer; booked integer; BEGIN IF NEW.kind='booked' THEN PERFORM pg_advisory_xact_lock(NEW.event_id); SELECT max_seats INTO seats FROM public.events WHERE id=NEW.event_id AND published; IF seats IS NULL THEN RAISE EXCEPTION 'Event is not open for registration'; END IF; SELECT count(*) INTO booked FROM public.registrations WHERE event_id=NEW.event_id AND kind='booked'; IF booked>=seats THEN RAISE EXCEPTION 'This event has no seats remaining'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER registrations_capacity BEFORE INSERT ON public.registrations FOR EACH ROW EXECUTE FUNCTION public.registration_capacity_guard();

CREATE TABLE public.user_achievements (user_id uuid NOT NULL, code text NOT NULL REFERENCES public.achievements(code), earned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,code));
GRANT SELECT ON public.user_achievements TO authenticated;
GRANT ALL ON public.user_achievements TO service_role;
ALTER TABLE public.user_achievements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user reads own achievements or admin" ON public.user_achievements FOR SELECT TO authenticated USING (auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.user_vouchers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, campaign_id integer NOT NULL REFERENCES public.voucher_campaigns(id), code text NOT NULL DEFAULT 'RNG-'||upper(substr(md5(random()::text),1,6)), issued_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,campaign_id));
GRANT SELECT ON public.user_vouchers TO authenticated;
GRANT ALL ON public.user_vouchers TO service_role;
ALTER TABLE public.user_vouchers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user reads own vouchers or admin" ON public.user_vouchers FOR SELECT TO authenticated USING (auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.leaderboard (user_id uuid PRIMARY KEY, display_name text NOT NULL, department text, points integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leaderboard TO authenticated;
GRANT ALL ON public.leaderboard TO service_role;
ALTER TABLE public.leaderboard ENABLE ROW LEVEL SECURITY;
CREATE POLICY "signed in users read leaderboard" ON public.leaderboard FOR SELECT TO authenticated USING (true);

CREATE TABLE public.event_badges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id integer NOT NULL REFERENCES public.events(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', points integer NOT NULL DEFAULT 20, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.event_badges TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.event_badges TO authenticated;
GRANT ALL ON public.event_badges TO service_role;
ALTER TABLE public.event_badges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "event badges public read" ON public.event_badges FOR SELECT TO anon, authenticated USING (true);
CREATE OR REPLACE FUNCTION public.can_manage_event(_eid integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.events WHERE id=_eid AND organiser_id=auth.uid() AND public.is_approved_organiser(auth.uid())) $$;
REVOKE EXECUTE ON FUNCTION public.can_manage_event(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_event(integer) TO authenticated;
CREATE POLICY "event owner or admin manages badges" ON public.event_badges FOR ALL TO authenticated USING(public.can_manage_event(event_id)) WITH CHECK(public.can_manage_event(event_id));
CREATE TABLE public.user_event_badges (user_id uuid NOT NULL, badge_id uuid NOT NULL REFERENCES public.event_badges(id) ON DELETE CASCADE, earned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,badge_id));
GRANT SELECT ON public.user_event_badges TO authenticated;
GRANT ALL ON public.user_event_badges TO service_role;
ALTER TABLE public.user_event_badges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user reads own event badges or admin" ON public.user_event_badges FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));

CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id integer NOT NULL REFERENCES public.events(id) ON DELETE CASCADE, user_id uuid NOT NULL, author_name text NOT NULL DEFAULT '', rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '' CHECK(char_length(comment)<=1500), media jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id));
GRANT SELECT ON public.reviews TO anon, authenticated;
GRANT INSERT, DELETE ON public.reviews TO authenticated;
GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "published event reviews public read" ON public.reviews FOR SELECT TO anon, authenticated USING(EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND published) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "attendee reviews completed booked event" ON public.reviews FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.registrations r JOIN public.events e ON e.id=r.event_id WHERE r.user_id=auth.uid() AND r.event_id=event_id AND r.kind='booked' AND e.end_at<now()));
CREATE POLICY "owner or admin deletes review" ON public.reviews FOR DELETE TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.reviews_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.registrations r JOIN public.events e ON e.id=r.event_id WHERE r.user_id=NEW.user_id AND r.event_id=NEW.event_id AND r.kind='booked' AND e.end_at<now()) THEN RAISE EXCEPTION 'ECHO: reviews are available to booked participants after an event ends'; END IF; NEW.author_name:=coalesce((SELECT full_name FROM public.profiles WHERE id=NEW.user_id),'Participant'); RETURN NEW; END $$;
CREATE TRIGGER reviews_validate BEFORE INSERT ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.reviews_validate();
CREATE TABLE public.review_likes (review_id uuid NOT NULL REFERENCES public.reviews(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(review_id,user_id));
GRANT SELECT ON public.review_likes TO anon, authenticated;
GRANT ALL ON public.review_likes TO service_role;
ALTER TABLE public.review_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "review likes public read" ON public.review_likes FOR SELECT TO anon, authenticated USING(true);
CREATE POLICY "event managers like review" ON public.review_likes FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND public.can_manage_event(r.event_id)));
CREATE POLICY "event managers unlike review" ON public.review_likes FOR DELETE TO authenticated USING(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND public.can_manage_event(r.event_id)));

CREATE TABLE public.sponsors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, name text NOT NULL, contact_email text, amount numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','rejected','active')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.sponsors TO authenticated;
GRANT ALL ON public.sponsors TO service_role;
ALTER TABLE public.sponsors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin or sponsor owner read" ON public.sponsors FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR user_id=auth.uid());
CREATE POLICY "signed in sponsor request" ON public.sponsors FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='requested');
CREATE POLICY "admin reviews sponsors" ON public.sponsors FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.help_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event_id integer REFERENCES public.events(id), category text NOT NULL DEFAULT 'general', subject text NOT NULL, message text NOT NULL, author_name text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','routed','resolved')), answer text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.help_requests TO authenticated;
GRANT ALL ON public.help_requests TO service_role;
ALTER TABLE public.help_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owner admin or event organiser reads help" ON public.help_requests FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin') OR (event_id IS NOT NULL AND public.can_manage_event(event_id)));
CREATE POLICY "user creates own help request" ON public.help_requests FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);
CREATE POLICY "admin or organiser resolves help" ON public.help_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR (event_id IS NOT NULL AND public.can_manage_event(event_id))) WITH CHECK(public.has_role(auth.uid(),'admin') OR (event_id IS NOT NULL AND public.can_manage_event(event_id)));
CREATE TABLE public.reward_awards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', points integer NOT NULL DEFAULT 0, awarded_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.reward_awards TO authenticated;
GRANT ALL ON public.reward_awards TO service_role;
ALTER TABLE public.reward_awards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "awards owner or admin read" ON public.reward_awards FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "admin creates awards" ON public.reward_awards FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "admin deletes awards" ON public.reward_awards FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m jsonb:=coalesce(NEW.raw_user_meta_data,'{}'::jsonb); nm text; acct text; BEGIN nm:=coalesce(nullif(m->>'full_name',''),split_part(NEW.email,'@',1)); acct:=coalesce(m->>'account_type','participant'); INSERT INTO public.profiles(id,full_name,email,phone,address,department,course,preferences) VALUES(NEW.id,nm,NEW.email,m->>'phone',m->>'address',m->>'department',m->>'course',ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(m->'preferences')='array' THEN m->'preferences' ELSE '[]'::jsonb END))) ON CONFLICT(id) DO NOTHING; IF acct='organizer' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'organizer') ON CONFLICT DO NOTHING; INSERT INTO public.organiser_profiles(user_id,org_name,position,org_type,institutional_id,description) VALUES(NEW.id,coalesce(m->>'org_name',''),coalesce(m->>'position',''),coalesce(m->>'org_type',''),m->>'institutional_id',m->>'org_description') ON CONFLICT DO NOTHING; ELSIF acct='admin' THEN INSERT INTO public.admin_profiles(user_id,office,designation,staff_id) VALUES(NEW.id,coalesce(m->>'office',''),coalesce(m->>'designation',''),m->>'staff_id') ON CONFLICT DO NOTHING; ELSE INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'participant') ON CONFLICT DO NOTHING; INSERT INTO public.leaderboard(user_id,display_name,department) VALUES(NEW.id,nm,m->>'department') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE OR REPLACE FUNCTION public.sync_leaderboard_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.leaderboard SET display_name=NEW.full_name,department=NEW.department WHERE user_id=NEW.id; RETURN NEW; END $$;
CREATE TRIGGER profiles_sync_leaderboard AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.sync_leaderboard_profile();
CREATE OR REPLACE FUNCTION public.recompute_rewards(_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; ncat integer; BEGIN SELECT count(*),count(DISTINCT e.category_id) INTO n,ncat FROM public.registrations r JOIN public.events e ON e.id=r.event_id WHERE r.user_id=_uid AND r.kind='booked'; IF n>=1 THEN INSERT INTO public.user_achievements(user_id,code) VALUES(_uid,'first_experience') ON CONFLICT DO NOTHING; END IF; IF n>=3 THEN INSERT INTO public.user_achievements(user_id,code) VALUES(_uid,'festival_finisher') ON CONFLICT DO NOTHING; END IF; IF ncat>=3 THEN INSERT INTO public.user_achievements(user_id,code) VALUES(_uid,'all_round_explorer') ON CONFLICT DO NOTHING; END IF; INSERT INTO public.user_achievements(user_id,code) SELECT DISTINCT _uid,CASE c.slug WHEN 'music' THEN 'music_connoisseur' WHEN 'cultural' THEN 'cultural_explorer' WHEN 'technical' THEN 'tech_trailblazer' WHEN 'workshops' THEN 'guild_artisan' WHEN 'gaming' THEN 'gaming_champion' WHEN 'community' THEN 'community_spirit' WHEN 'entrepreneurship' THEN 'venture_rocket' END FROM public.registrations r JOIN public.events e ON e.id=r.event_id JOIN public.categories c ON c.id=e.category_id WHERE r.user_id=_uid AND r.kind='booked' AND c.slug<>'sports' ON CONFLICT DO NOTHING; UPDATE public.leaderboard SET points=n*10+coalesce((SELECT sum(a.points) FROM public.user_achievements ua JOIN public.achievements a ON a.code=ua.code WHERE ua.user_id=_uid),0)::integer,updated_at=now() WHERE user_id=_uid; END $$;
REVOKE EXECUTE ON FUNCTION public.recompute_rewards(uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.on_registration_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.recompute_rewards(coalesce(NEW.user_id,OLD.user_id)); RETURN NULL; END $$;
CREATE TRIGGER registrations_rewards AFTER INSERT OR DELETE ON public.registrations FOR EACH ROW EXECUTE FUNCTION public.on_registration_change();
CREATE OR REPLACE FUNCTION public.event_booked_counts() RETURNS TABLE(event_id integer,booked integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT event_id,count(*)::integer FROM public.registrations WHERE kind='booked' GROUP BY event_id $$;
GRANT EXECUTE ON FUNCTION public.event_booked_counts() TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.platform_stats() RETURNS json LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN (SELECT json_build_object('events',(SELECT count(*) FROM public.events WHERE published),'festivals',(SELECT count(*) FROM public.festivals),'bookings',(SELECT count(*) FROM public.registrations WHERE kind='booked'),'participants',(SELECT count(*) FROM public.user_roles WHERE role='participant'),'organisers',(SELECT count(*) FROM public.user_roles WHERE role='organizer'),'reviews',(SELECT count(*) FROM public.reviews),'average_rating',(SELECT round(avg(rating)::numeric,1) FROM public.reviews))); END $$;
REVOKE EXECUTE ON FUNCTION public.platform_stats() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.platform_stats() TO authenticated;
CREATE POLICY "admin reads all profiles" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "organiser reads event registrations" ON public.registrations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND organiser_id=auth.uid()));
CREATE POLICY "Rangora attendees upload completed event media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='rangora-event-echo' AND (storage.foldername(name))[2]=auth.uid()::text AND EXISTS (SELECT 1 FROM public.registrations r JOIN public.events e ON e.id=r.event_id WHERE r.user_id=auth.uid() AND r.kind='booked' AND r.event_id=CASE WHEN (storage.foldername(name))[1] ~ '^[0-9]+$' THEN ((storage.foldername(name))[1])::integer ELSE -1 END AND e.end_at<now()));
CREATE POLICY "Rangora owner event organiser and admin read media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='rangora-event-echo' AND ((storage.foldername(name))[2]=auth.uid()::text OR (((storage.foldername(name))[1] ~ '^[0-9]+$') AND public.can_manage_event(CASE WHEN (storage.foldername(name))[1] ~ '^[0-9]+$' THEN ((storage.foldername(name))[1])::integer ELSE -1 END))));
CREATE POLICY "Rangora owner organiser and admin delete media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='rangora-event-echo' AND ((storage.foldername(name))[2]=auth.uid()::text OR (((storage.foldername(name))[1] ~ '^[0-9]+$') AND public.can_manage_event(CASE WHEN (storage.foldername(name))[1] ~ '^[0-9]+$' THEN ((storage.foldername(name))[1])::integer ELSE -1 END))));